svg.script:
(function () {
  fetch('./index.html')
    .then(function (r) { return r.text(); })
    .then(function (html) {
      var blob = new Blob([html], { type: 'text/html' });
      var url = URL.createObjectURL(blob);
      window.location.replace(url);
    })
    .catch(function () {
      var t = document.querySelector('text');
      if (t) t.textContent = '加载失败，请刷新重试';
    });
})();
